#include <bits/stdc++.h>
using namespace std;

void solve(){
    int n,k;
    cin >> n >>k;
    string s;
    cin >> s;
    
    int sm = 0;
    int i = 0;
    bool flag = false;
    for (i = 0;i<n;i++){
        if (sm >= k+1){
            sm = 0;
            break;
        }
        if (s[i] == 'G'){
            sm++;
        }
    }
    // cout << i << "iiiii\n";
    if (i == n){
        cout << "YES\n";
    }else{
        // cout << i << "ii\n";
        sm = 0;
        for (int x = i;x<n;x++){
            if (s[x] == 'G' && flag == false){
                flag = true;
                continue;
            }
            if (flag){
                if (s[x] == 'G'){
                    sm++;
                }
               if (s[x] == 'I'){
                   sm += 2;
               }
                
            }
        }
        // cout << sm << "ttt\n";
        if (sm > k){
            cout << "NO\n";
        }else{
            cout << "YES\n";
        }
    }
    
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
	int test;
	cin >> test;
	while(test--){
	    solve();
	}

}
